-- ---------------------------------------------------------------------------
-- Phase 5 data load: the real Spinnaker Railing (updated), Spinnaker
-- Windows, and TRAT Windows master registers.
--
-- Generated from:
--   XA_DOS_Spinnaker_Glass_Railing_Master_Register.xlsx (Master Railing
--     Register sheet) -- includes a fix for a data-entry error: 'GR-260'
--     was used for 3 different real locations (17th/18th/19th floor,
--     different units and measurements); renumbered to GR-260/261/262 in
--     the order they appeared, per owner confirmation. No other data
--     changed. Brings the Spinnaker Railing register to 262 locations
--     (up from the 240 currently live).
--   XA_DOS_Spinnaker_Windows_Master_Register.xlsx / XA_DOS_TRAT_Windows_
--     Master_Register.xlsx -- both independently number locations
--     'AGD-001'... with 529 identical labels colliding between the two
--     projects, so the DB id is prefixed per project ('SPN-AGD-001',
--     'TRAT-AGD-001'); the original label is preserved as `reference`,
--     which is what the app displays to field crews.
--
--   All three registers' own "Project Code" column ('PRJ-2607002' /
--   'PRJ-2607003') is missing a digit relative to the real project codes
--   used everywhere else in XA DOS (confirmed against
--   xa_dos_migrations/19_project_roster_and_scoping.sql and
--   18_quo_to_prj_on_award.sql: 'PRJ-26070002' / 'PRJ-26070003') -- this
--   migration substitutes the correct 8-digit codes rather than trusting
--   the register's column verbatim; using the register's value as-is
--   would have silently orphaned every row (never matching the project a
--   user actually has selected in the app).
--
-- Safe to re-run: upserts by id. On conflict, only the register's own
-- "spec" fields are updated (floor, unit, measurements, tag/system,
-- reference) -- status, priority, assigned_team, and remarks are
-- deliberately left untouched on an existing row, so this can never
-- clobber real field progress already logged against the 240 Railing
-- locations live today. New rows (the 22 new Railing locations, and every
-- Doors & Windows row -- all new) get their full register values,
-- including status defaulting to 'Not Started' where the register left
-- it blank.
--
-- Requires supabase/07_doors_windows_locations.sql to have been run first
-- (adds the reference/window_tag/window_system/tower_building columns and
-- loosens the now-scope-agnostic columns to nullable).
-- ---------------------------------------------------------------------------

on conflict (id) do update set
  reference = excluded.reference,
  project_code = excluded.project_code,
  floor_level = excluded.floor_level,
  unit_no = excluded.unit_no,
  unit_type = excluded.unit_type,
  total_linear_meters = excluded.total_linear_meters,
  total_glass_panels = excluded.total_glass_panels,
  bracket_system = excluded.bracket_system,
  window_tag = excluded.window_tag,
  window_system = excluded.window_system,
  tower_building = excluded.tower_building,
  scope = excluded.scope;
  -- status / priority / assigned_team / remarks intentionally NOT
  -- updated on conflict -- see header note.

on conflict (id) do update set
